@rule("s26", "s26", otherwise="NotMentioned")
def assignment_prohibition():
    return "Contradiction" if "assignment" in "Neither Party shall have the right to assign this Agreement without the prior written consent of the other Party." else "NotMentioned"

@rule("s28", "s28", otherwise="NotMentioned")
def governing_law():
    return "Entailment" if "Sweden" in "This Agreement shall be construed in accordance with and be governed by the substantive laws of Sweden." else "NotMentioned"

@rule("s36", "s36", otherwise="NotMentioned")
def reverse_engineering():
    return "Contradiction" if "reverse engineer" in "Receiving Party shall not reverse engineer any objects which embody Disclosing Party's Confidential Information." else "NotMentioned"

query = "Entailment" if governing_law() == "Entailment" and assignment_prohibition() == "Contradiction" and reverse_engineering() == "Contradiction" else "NotMentioned"
